from equipment_catalog import EquipmentCatalog

def _ok(val):
    return {'ok': True, 'data': val}

def _err(code):
    return {'ok': False, 'error': {'code': code}}

def _snap(cat, eid):
    r = cat.get_equipment(eid)
    assert r['ok'] is True
    return r['data']['status']

cat = EquipmentCatalog()
r1 = cat.register('CAM-1')
assert r1 == _ok({'equipment_id': 'CAM-1', 'status': 'AVAILABLE'})
r2 = cat.register('CAM-1')
assert r2 == _err('DUPLICATE')
r3 = cat.register('cam-1')
assert r3 == _ok({'equipment_id': 'cam-1', 'status': 'AVAILABLE'})

