TASK-IMPL-CATALOG.Methods with '' or 123 as equipment_id r:
from equipment_catalog import EquipmentCatalog

def _ok(val):
    return {'ok': True, 'data': val}

def _err(code):
    return {'ok': False, 'error': {'code': code}}

def _snap(cat, eid):
    r = cat.get_equipment(eid)
    assert r['ok'] is True
    return r['data']['status']

cat = EquipmentCatalog()
for method in (cat.register, cat.get_equipment, cat.claim, cat.release):
    for bad in ('', 123):
        r = method(bad)
        assert r == _err('INVALID_ARGUMENT'), f'{method}({bad!r}) -> {r}'
